SELECT role
FROM public.user_platform_roles
WHERE user_id = #{userId}

SELECT EXISTS (
    SELECT 1
    FROM public.user_platform_roles
    WHERE user_id = #{userId}
      AND role    = #{role}
)

mapper.delete:
DELETE FROM public.user_platform_roles
WHERE user_id = #{userId}
  AND role    = #{role}
